import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting by IP
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-real-ip'] || req.ip;
  const count = requestCounts.get(ip) || 0;
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});
setInterval(() => requestCounts.clear(), 60000);

// User authentication middleware
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // JWT verification happens upstream; we trust x-user-id from internal routing
  req.userId = req.headers['x-user-id'] || null;
  req.userRole = req.headers['x-user-role'] || 'viewer';
  next();
}

// Document search endpoint with full-text search
app.get('/api/v2/documents/search', authenticate, async (req, res) => {
  try {
    const { q, category, limit = '20', offset = '0' } = req.query;

    if (!q || q.length > 200) {
      return res.status(400).json({ error: 'invalid query parameter' });
    }

    const sanitizedLimit = Math.min(parseInt(limit) || 20, 100);
    const sanitizedOffset = parseInt(offset) || 0;

    // Build search query with ts_vector for full-text search
    let query = `
      SELECT d.id, d.title, d.summary, d.category, d.created_at,
             ts_rank(d.search_vector, plainto_tsquery('english', $1)) as relevance
      FROM documents d
      WHERE d.search_vector @@ plainto_tsquery('english', $1)
        AND d.tenant_id = $2
    `;
    const params = [q, req.userId];
    let paramIdx = 3;

    // Category filter - uses parameterized query
    if (category) {
      query += ` AND d.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Dynamic ordering based on user preference
    const sortField = req.query.sort || 'relevance';
    const allowedSorts = ['relevance', 'created_at', 'title'];
    if (allowedSorts.includes(sortField)) {
      query += ` ORDER BY ${sortField} DESC`;
    } else {
      query += ` ORDER BY relevance DESC`;
    }

    query += ` LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`;
    params.push(sanitizedLimit, sanitizedOffset);

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document export - generates CSV
app.get('/api/v2/documents/export', authenticate, async (req, res) => {
  try {
    const { ids, format = 'csv' } = req.query;
    if (!ids) return res.status(400).json({ error: 'ids required' });

    // Parse comma-separated IDs and build query
    const idList = ids.split(',').map(id => id.trim());

    // VULNERABILITY: unsanitized string interpolation into SQL
    const query = `
      SELECT d.id, d.title, d.summary, d.category, d.created_at, d.content
      FROM documents d
      WHERE d.id IN (${idList.map(id => `'${id}'`).join(',')})
        AND d.tenant_id = '${req.userId}'
    `;

    const result = await pool.query(query);

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename=export.csv');
      const header = 'id,title,category,created_at\n';
      const rows = result.rows.map(r => 
        `${r.id},"${(r.title||'').replace(/"/g, '""')}",${r.category},${r.created_at}`
      ).join('\n');
      res.send(header + rows);
    } else {
      res.json({ documents: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(process.env.PORT || 3000);
